/bin/bash -lc "python3 -m py_compile /workspace/openai_client.py && python3 - <<'PY'
import json
from unittest.mock import patch
import openai_client

class FakeResponse:
    def __enter__(self): return self
    def __exit__(self, *args): pass
    def read(self):
        return json.dumps({\"output\": [{\"type\": \"message\", \"content\": [{\"type\": \"output_text\", \"text\": \"hello\"}]}]}).encode()

captured = {}
def fake_urlopen(request, timeout):
    captured[\"url\"] = request.full_url
    captured[\"authorization\"] = request.headers[\"Authorization\"]
    captured[\"body\"] = json.loads(request.data)
    captured[\"timeout\"] = timeout
    return FakeResponse()

with patch(\"urllib.request.urlopen\", fake_urlopen):
    assert openai_client.respond(\"private\", api_key=\"test-key\") == \"hello\"
assert captured == {
    \"url\": \"https://api.openai.com/v1/responses\",
    \"authorization\": \"Bearer test-key\",
    \"body\": {\"model\": \"gpt-5\", \"input\": \"private\", \"store\": False},
    \"timeout\": 60.0,
}
print(\"compile and mocked request test passed\")
PY"

